//! The release publishes one feature manifest per build (#307), so a download
//! carries a machine-readable answer to "which capability is in this build?"
//! rather than only the prose in the notes (#303 is where that prose gap
//! hurt). The manifest is generated by `scripts/feature-manifest.sh` from the
//! exact feature set the build compiled, because the workflow knows that for
//! certain and no single binary can see another crate's features.
//!
//! That script only runs during a release, so these tests pin its output
//! shape on every pull request, the way `release_version_check.rs` pins the
//! version check. A manifest whose shape drifted would be read by whatever
//! consumes it (a human, or a later tool) as a different answer.

use std::path::{Path, PathBuf};
use std::process::Command;

fn script() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("scripts/feature-manifest.sh")
}

fn run(args: &[&str]) -> String {
    let out = Command::new("sh")
        .arg(script())
        .args(args)
        .output()
        .expect("run feature-manifest.sh");
    assert!(
        out.status.success(),
        "feature-manifest.sh failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    String::from_utf8(out.stdout).expect("utf8 manifest")
}

#[test]
fn a_default_build_has_an_empty_feature_array() {
    let manifest = run(&["v0.8.0", "x86_64-unknown-linux-gnu", ""]);
    assert_eq!(
        manifest.trim(),
        r#"{"version":"v0.8.0","target":"x86_64-unknown-linux-gnu","features":[]}"#
    );
}

#[test]
fn features_are_sorted_deduped_and_trimmed() {
    // A trailing comma, a duplicate, and surrounding spaces are all the kinds
    // of noise a workflow string can carry; none should reach the manifest.
    let manifest = run(&["v0.8.0", "aarch64-apple-darwin", "voice, train,voice,"]);
    assert_eq!(
        manifest.trim(),
        r#"{"version":"v0.8.0","target":"aarch64-apple-darwin","features":["train","voice"]}"#
    );
}

/// The DMG manifest's feature set is read in `desktop.yml` from the bridge
/// crate's `default = [...]` (what `build-bridge.sh` actually compiles). This
/// pins that path: it parses the real `bridge/Cargo.toml` the same way, feeds
/// it to the script, and asserts the manifest records that exact set. If the
/// bridge default changes, this expectation changes with it rather than
/// drifting from a hardcoded list; if the default array is ever wrapped onto
/// several lines so the single-line parse yields nothing, the non-empty
/// assertion fails loudly here, the same case `desktop.yml` now guards at run
/// time.
#[test]
fn the_dmg_manifest_matches_the_bridge_default_features() {
    let bridge = Path::new(env!("CARGO_MANIFEST_DIR")).join("zorp-desktop/bridge/Cargo.toml");
    let text = std::fs::read_to_string(&bridge).expect("read bridge Cargo.toml");
    // The same extraction as desktop.yml: the single `default = [ ... ]` line.
    let line = text
        .lines()
        .find(|l| l.trim_start().starts_with("default = ["))
        .expect("bridge has a default feature line");
    let inner = line
        .split_once('[')
        .and_then(|(_, r)| r.rsplit_once(']'))
        .map(|(mid, _)| mid)
        .expect("default line has brackets");
    let mut feats: Vec<String> = inner
        .split(',')
        .map(|f| f.trim().trim_matches('"').to_string())
        .filter(|f| !f.is_empty())
        .collect();
    assert!(!feats.is_empty(), "bridge default features parsed empty");
    feats.sort();
    feats.dedup();

    let csv = feats.join(",");
    let manifest = run(&["v0.8.0", "universal-apple-darwin-dmg", &csv]);
    let expected_features = feats
        .iter()
        .map(|f| format!("\"{f}\""))
        .collect::<Vec<_>>()
        .join(",");
    let expected = format!(
        r#"{{"version":"v0.8.0","target":"universal-apple-darwin-dmg","features":[{expected_features}]}}"#
    );
    assert_eq!(manifest.trim(), expected);
}

#[test]
fn version_and_target_are_required() {
    let out = Command::new("sh")
        .arg(script())
        .arg("v0.8.0")
        .output()
        .expect("run feature-manifest.sh");
    assert!(!out.status.success(), "missing target should fail");
}
